        }

        // 함수 시그니처 검사
        const signature = this.vtFunctions.get(instr.function);
        if (instr.args.length !== signature.params.length) {
          throw new TypeError(
            `${instr.function} expects ${signature.params.length} arguments, got ${instr.args.length}`
