      }
      return this.scope.get(expr.name);
    } else if (expr.type === "arithmetic") {
      // 산술 연산은 숫자를 반환
      return "f64"; // 또는 더 정교한 타입 추론
    }
    // ... 다른 표현식 타입들
    return "any";
  }

