// ====== Test 10: 주석 ======
runner.test("Test 10: 주석 지원", () => {
  const program = {
    version: "6.0",
    instructions: [
      {
        type: "comment",
        text: "이것은 주석입니다",
      },
      {
        type: "var",
        name: "x",
        value_type: "i32",
        value: 42,
      },
    ],
  };

  const result = runner.compiler.compile(program);
  runner.assert(result.success, "컴파일 실패");
  runner.assert(
