            `${instr.function} expects ${signature.params.length} arguments, got ${instr.args.length}`
          );
        }

        // 반환값을 scope에 추가
        if (instr.assign_to) {
          this.scope.set(instr.assign_to, signature.returnType);
        }
        break;

      case "condition":
        // 조건 검사
        this.checkInstruction({
          type: "call",
          function: "dummy",
          args: [instr.test],
        });
        break;

      case "loop":
        // 범위 검사
        const rangeType = this.inferType(instr.range);
