          if (rangeType !== "Range") {
            throw new Error(`Loop range must be Array or Range, got ${rangeType}`);
          }
        }
        break;
    }
  }

  inferType(expr) {
    if (!expr) {
      return "any";
    }

    if (expr.type === "literal") {
      return expr.value_type;
    } else if (expr.type === "ref") {
