    if (from === "any" || to === "any") return true;
    if (from === "i32" && to === "f64") return true; // 정수 → 실수
    return false;
  }

  /**
   * VT 코드 생성
   */
  generateVTCode(ast) {
    const lines = [
      "; CLAUDELang v6.0 compiled to VT",
      "; Generated code below",
      "",
