const CLAUDELangCompiler = require("/data/data/com.termux/files/home/freelang-v6-ai-sovereign/src/compiler.js");

const compiler = new CLAUDELangCompiler();

console.log("=== CLAUDELang v6.0 최종 검증 ===\n");

// Test Suite
const tests = [
  {
    name: "배열 타입 정확한 추론",
    program: {
      version: "6.0",
      instructions: [
        {
          type: "var",
          name: "nums",
          value_type: "Array<i32>",
          value: { type: "array", elements: [{ type: "literal", value_type: "i32", value: 1 }] },
        },
      ],
    },
    checks: [
      (r) => r.success === true,
      (r) => r.code.includes("(array 1)"),
    ],
  },
  {
    name: "타입 불일치 감지",
    program: {
      version: "6.0",
      instructions: [
        { type: "var", name: "x", value_type: "i32", value: "wrong" },
      ],
    },
    checks: [
      (r) => r.success === false,
      (r) => r.errors[0].includes("Cannot assign string to i32"),
    ],
  },
  {
    name: "람다 함수 본체 생성",
    program: {
      version: "6.0",
      instructions: [
        {
          type: "var",
          name: "arr",
          value_type: "Array<i32>",
          value: { type: "array", elements: [{ type: "literal", value_type: "i32", value: 1 }] },
        },
        {
          type: "call",
          function: "Array.map",
          args: [
            { type: "ref", name: "arr" },
            {
              type: "lambda",
              params: [{ name: "x", type: "i32" }],
              body: [{ type: "arithmetic", operator: "*", left: { type: "ref", name: "x" }, right: { type: "literal", value_type: "i32", value: 2 } }],
            },
          ],
          assign_to: "result",
        },
      ],
    },
    checks: [
      (r) => r.success === true,
      (r) => r.code.includes("(fn (x) (* x 2))"),
    ],
  },
];

let passed = 0;
let failed = 0;

tests.forEach((test) => {
  try {
    const result = compiler.compile(test.program);
    let allChecksPassed = true;

    for (const check of test.checks) {
      if (!check(result)) {
        allChecksPassed = false;
        break;
      }
    }

    if (allChecksPassed) {
      console.log(`✅ ${test.name}`);
      passed++;
    } else {
      console.log(`❌ ${test.name}`);
      console.log(`   Result:`, result);
      failed++;
    }
  } catch (e) {
    console.log(`❌ ${test.name}`);
    console.log(`   Error: ${e.message}`);
    failed++;
  }
});

console.log(`\n결과: ${passed}/${tests.length} 통과`);
process.exit(failed === 0 ? 0 : 1);
EOF
