/**
 * CLAUDELang v6.0 Cached Compiler
 * 컴파일 결과 캐싱을 통한 성능 최적화
 *
 * 최적화:
 * 1. 전체 AST 캐싱
 * 2. 부분 컴파일 결과 캐싱
 * 3. 함수 시그니처 캐싱
 */

const crypto = require("crypto");
const CLAUDELangCompiler = require("./compiler.js");

class CachedCLAUDELangCompiler extends CLAUDELangCompiler {
  constructor(maxCacheSize = 1000) {
    super();
    this.cache = new Map(); // 컴파일 결과 캐시
    this.astCache = new Map(); // AST 파싱 결과 캐시
    this.maxCacheSize = maxCacheSize;
    this.cacheHits = 0;
    this.cacheMisses = 0;
  }

  /**
   * 입력 프로그램의 해시 생성
   * 동일한 입력을 빠르게 식별하기 위함
   */
  generateHash(data) {
    const str = JSON.stringify(data);
    return crypto.createHash("md5").update(str).digest("hex");
  }

  /**
   * 캐시 크기 관리 (LRU 정책)
   */
  evictIfNeeded() {
    if (this.cache.size > this.maxCacheSize) {
      // 가장 오래된 항목 제거
      const firstKey = this.cache.keys().next().value;
      this.cache.delete(firstKey);
    }
  }

  /**
   * 최적화된 컴파일 (캐싱 포함)
   */
  compile(claudelangJson) {
    // 입력 해시 생성
    const hash = this.generateHash(claudelangJson);

    // 캐시 확인
    if (this.cache.has(hash)) {
      this.cacheHits++;
      return this.cache.get(hash);
    }

    this.cacheMisses++;

    // 원본 컴파일 실행
    const result = super.compile(claudelangJson);

    // 결과 캐싱
    this.cache.set(hash, result);
    this.evictIfNeeded();

    return result;
  }

  /**
   * 검증만 캐싱 (빠른 검증)
   */
  validateCached(obj) {
    const hash = this.generateHash(obj);
    const cacheKey = `validate_${hash}`;

    if (this.cache.has(cacheKey)) {
      return true; // 이미 검증됨
    }

    try {
      super.validate(obj);
      this.cache.set(cacheKey, { validated: true });
      return true;
    } catch (error) {
      return false;
    }
  }

  /**
   * 부분 AST 캐싱을 통한 개별 명령어 컴파일
   */
  compileInstruction(instruction) {
    const hash = this.generateHash(instruction);
    const cacheKey = `instr_${hash}`;

    if (this.cache.has(cacheKey)) {
      this.cacheHits++;
      return this.cache.get(cacheKey);
    }

    this.cacheMisses++;

    try {
      const result = this.generateInstruction(instruction);
      this.cache.set(cacheKey, result);
      this.evictIfNeeded();
      return result;
    } catch (error) {
      return null;
    }
  }

  /**
   * 캐시 통계
   */
  getCacheStats() {
    const total = this.cacheHits + this.cacheMisses;
    const hitRate = total === 0 ? 0 : (this.cacheHits / total) * 100;

    return {
      cacheSize: this.cache.size,
      maxCacheSize: this.maxCacheSize,
      hits: this.cacheHits,
      misses: this.cacheMisses,
      total: total,
      hitRate: hitRate.toFixed(2) + "%",
      efficiency: ((this.cacheHits * 100) / (total || 1)).toFixed(2),
    };
  }

  /**
   * 캐시 초기화
   */
  clearCache() {
    this.cache.clear();
    this.cacheHits = 0;
    this.cacheMisses = 0;
  }

  /**
   * 캐시 상태 출력
   */
  printCacheStats() {
    const stats = this.getCacheStats();
    console.log("\n");
    console.log("╔" + "═".repeat(50) + "╗");
    console.log("║" + " Cache Statistics".padEnd(50) + "║");
    console.log("╠" + "═".repeat(50) + "╣");
    console.log(`║ Cache Size: ${stats.cacheSize}/${stats.maxCacheSize}`.padEnd(51) + "║");
    console.log(`║ Hits: ${stats.hits}, Misses: ${stats.misses}`.padEnd(51) + "║");
    console.log(`║ Hit Rate: ${stats.hitRate}`.padEnd(51) + "║");
    console.log("╚" + "═".repeat(50) + "╝\n");
  }
}

module.exports = CachedCLAUDELangCompiler;

/**
 * CLAUDELang v6.0 Optimized VT Runtime
 * VT 바이트코드 실행 엔진 (최적화 버전)
 *
 * 최적화:
 * 1. 메모리 풀 관리 (객체 재사용)
 * 2. 불필요한 복사 제거
 * 3. 변수 접근 최적화 (직접 참조)
 * 4. JIT 컴파일 준비 (미래 확장)
 */

class OptimizedVTRuntime {
  constructor(options = {}) {
    this.variables = new Map();
    this.functions = new Map();
    this.output = [];

    // 최적화 옵션
    this.options = {
      poolSize: options.poolSize || 1000,
      enableMemoryPool: options.enableMemoryPool !== false,
      enableDirectAccess: options.enableDirectAccess !== false,
      enableInlining: options.enableInlining !== false,
      ...options,
    };

    // 메모리 풀 초기화
    this.objectPool = [];
    this.arrayPool = [];
    this.stringPool = new Set();

    if (this.options.enableMemoryPool) {
      this.initializePools();
    }

    // 접근 최적화: 빈번하게 사용되는 변수 캐시
    this.accessCache = new Map();

    this.registerBuiltinFunctions();
  }

  /**
   * 메모리 풀 초기화
   */
  initializePools() {
    for (let i = 0; i < this.options.poolSize; i++) {
      this.objectPool.push({});
      this.arrayPool.push([]);
    }
  }

  /**
   * 객체 풀에서 객체 할당
   */
  allocateObject() {
    if (this.options.enableMemoryPool && this.objectPool.length > 0) {
      return this.objectPool.pop();
    }
    return {};
  }

  /**
   * 객체를 풀에 반환
   */
  deallocateObject(obj) {
    if (this.options.enableMemoryPool) {
      // 객체 초기화
      for (const key in obj) {
        delete obj[key];
      }
      this.objectPool.push(obj);
    }
  }

  /**
   * 배열 풀에서 배열 할당
   */
  allocateArray(size = 0) {
    if (this.options.enableMemoryPool && this.arrayPool.length > 0) {
      const arr = this.arrayPool.pop();
      arr.length = 0; // 초기화
      return arr;
    }
    return new Array(size);
  }

  /**
   * 배열을 풀에 반환
   */
  deallocateArray(arr) {
    if (this.options.enableMemoryPool) {
      arr.length = 0;
      this.arrayPool.push(arr);
    }
  }

  /**
   * 직접 접근을 위한 변수 캐시
   */
  cacheVariable(name) {
    if (this.options.enableDirectAccess && !this.accessCache.has(name)) {
      const value = this.variables.get(name);
      if (value !== undefined) {
        this.accessCache.set(name, value);
      }
    }
  }

  /**
   * 변수 접근 (최적화)
   */
  getVariable(name) {
    // 캐시에서 먼저 확인
    if (this.options.enableDirectAccess && this.accessCache.has(name)) {
      return this.accessCache.get(name);
    }

    // 원본 저장소에서 조회
    const value = this.variables.get(name);

    // 캐시 업데이트
    if (value !== undefined) {
      this.cacheVariable(name);
    }

    return value;
  }

  /**
   * 변수 설정 (캐시 무효화 포함)
   */
  setVariable(name, value) {
    this.variables.set(name, value);
    // 캐시 무효화
    if (this.options.enableDirectAccess) {
      this.accessCache.set(name, value);
    }
  }

  /**
   * 내장 함수 등록
   */
  registerBuiltinFunctions() {
    // Array 함수들
    this.registerFunction("Array.map", (arr, fn) => {
      const result = this.allocateArray(arr.length);
      for (let i = 0; i < arr.length; i++) {
        result[i] = fn(arr[i]);
      }
      return result;
    });

    this.registerFunction("Array.filter", (arr, fn) => {
      const result = this.allocateArray();
      for (let i = 0; i < arr.length; i++) {
        if (fn(arr[i])) {
          result.push(arr[i]);
        }
      }
      return result;
    });

    this.registerFunction("Array.reduce", (arr, fn, init) => {
      let acc = init;
      for (let i = 0; i < arr.length; i++) {
        acc = fn(acc, arr[i]);
      }
      return acc;
    });

    this.registerFunction("Array.find", (arr, fn) => {
      for (let i = 0; i < arr.length; i++) {
        if (fn(arr[i])) {
          return arr[i];
        }
      }
      return undefined;
    });

    // String 함수들
    this.registerFunction("String.split", (str, delimiter) => {
      return str.split(delimiter);
    });

    this.registerFunction("String.join", (arr, delimiter) => {
      return arr.join(delimiter);
    });

    this.registerFunction("String.upper", (str) => {
      return str.toUpperCase();
    });

    this.registerFunction("String.lower", (str) => {
      return str.toLowerCase();
    });

    this.registerFunction("String.trim", (str) => {
      return str.trim();
    });

    // Math 함수들
    this.registerFunction("Math.sqrt", (x) => Math.sqrt(x));
    this.registerFunction("Math.pow", (x, y) => Math.pow(x, y));
    this.registerFunction("Math.abs", (x) => Math.abs(x));

    // JSON 함수들
    this.registerFunction("JSON.parse", (str) => JSON.parse(str));
    this.registerFunction("JSON.stringify", (obj) => JSON.stringify(obj));

    // Print
    this.registerFunction("print", (value) => {
      this.output.push(String(value));
      console.log(value);
    });
  }

  /**
   * 함수 등록
   */
  registerFunction(name, fn) {
    this.functions.set(name, fn);
  }

  /**
   * 함수 호출
   */
  callFunction(name, args) {
    const fn = this.functions.get(name);
    if (!fn) {
      throw new Error(`Unknown function: ${name}`);
    }
    return fn(...args);
  }

  /**
   * VT 코드 라인 실행 (단순화된 버전)
   */
  executeLine(line) {
    if (!line || line.startsWith(";")) {
      return null; // 주석 또는 빈 줄
    }

    // 간단한 파싱 (실제로는 VT 인터프리터 필요)
    // 현재는 구조만 제시

    // (define x 42) 형태
    if (line.startsWith("(define ")) {
      const match = line.match(/\(define\s+(\w+)\s+(.+)\)/);
      if (match) {
        const varName = match[1];
        const value = this.evaluateExpression(match[2]);
        this.setVariable(varName, value);
        return value;
      }
    }

    // (call function arg1 arg2) 형태
    if (line.startsWith("(call ")) {
      const match = line.match(/\(call\s+(\S+)\s*(.*)\)/);
      if (match) {
        const funcName = match[1];
        const argsStr = match[2];
        const args = argsStr ? argsStr.split(/\s+/).map((a) => this.evaluateExpression(a)) : [];
        return this.callFunction(funcName, args);
      }
    }

    return null;
  }

  /**
   * 간단한 식 평가
   */
  evaluateExpression(expr) {
    // 숫자
    if (/^\d+$/.test(expr)) {
      return parseInt(expr);
    }

    // 문자열
    if (expr.startsWith('"') && expr.endsWith('"')) {
      return expr.slice(1, -1);
    }

    // 변수 참조
    if (/^[a-zA-Z_]\w*$/.test(expr)) {
      return this.getVariable(expr);
    }

    return expr;
  }

  /**
   * 전체 프로그램 실행
   */
  execute(vtCode) {
    const lines = vtCode.split("\n");
    const results = [];

    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed) {
        const result = this.executeLine(trimmed);
        if (result !== null && result !== undefined) {
          results.push(result);
        }
      }
    }

    return {
      success: true,
      results: results,
      output: this.output,
      variables: Object.fromEntries(this.variables),
    };
  }

  /**
   * 메모리 통계
   */
  getMemoryStats() {
    return {
      variableCount: this.variables.size,
      functionCount: this.functions.size,
      pooledObjects: this.objectPool.length,
      pooledArrays: this.arrayPool.length,
      accessCacheSize: this.accessCache.size,
      totalOutput: this.output.length,
    };
  }

  /**
   * 런타임 정리
   */
  cleanup() {
    this.variables.clear();
    this.accessCache.clear();
    this.output = [];

    if (this.options.enableMemoryPool) {
      this.objectPool = [];
      this.arrayPool = [];
      this.initializePools();
    }
  }

  /**
   * 성능 통계 출력
   */
  printStats() {
    const stats = this.getMemoryStats();
    console.log("\n");
    console.log("╔" + "═".repeat(50) + "╗");
    console.log("║" + " Runtime Statistics".padEnd(50) + "║");
    console.log("╠" + "═".repeat(50) + "╣");
    console.log(`║ Variables: ${stats.variableCount}`.padEnd(51) + "║");
    console.log(`║ Functions: ${stats.functionCount}`.padEnd(51) + "║");
    console.log(`║ Pooled Objects: ${stats.pooledObjects}`.padEnd(51) + "║");
    console.log(`║ Access Cache: ${stats.accessCacheSize}`.padEnd(51) + "║");
    console.log("╚" + "═".repeat(50) + "╝\n");
  }
}

module.exports = OptimizedVTRuntime;

/**
 * CLAUDELang v6.0 통합 시스템
 *
 * 기능:
 * 1. JSON 파일 읽기
 * 2. 컴파일러를 통한 VT 바이트코드 생성
 * 3. VT 런타임에서 실행
 * 4. 결과값 추출 및 검증
 */

const fs = require('fs');
const path = require('path');
const CLAUDELangCompiler = require('./compiler.js');

/**
 * 향상된 VT 런타임
 * Array.map, Array.filter 등의 고차 함수 지원
 */
class VTRuntime {
  constructor() {
    this.scope = new Map();
    this.output = [];
    this.executionTime = 0;
    this.memoryUsage = 0;
    this.instructionCount = 0;
    this.lastResult = undefined;
  }

  /**
   * VT 코드 실행
   */
  execute(vtCode) {
    const startTime = Date.now();
    const startMem = process.memoryUsage().heapUsed;

    try {
      const lines = vtCode.split('\n').filter(line => {
        return line.trim() && !line.trim().startsWith(';');
      });

      for (const line of lines) {
        this.executeSExpression(line.trim());
        this.instructionCount++;
      }

      const endTime = Date.now();
      const endMem = process.memoryUsage().heapUsed;

      this.executionTime = endTime - startTime;
      this.memoryUsage = Math.max(0, (endMem - startMem) / 1024 / 1024);

      return {
        success: true,
        output: this.output,
        result: this.lastResult,
        executionTime: this.executionTime,
        memoryUsage: this.memoryUsage,
        instructionCount: this.instructionCount,
      };
    } catch (error) {
      return {
        success: false,
        output: this.output,
        error: error.message,
        executionTime: Date.now() - startTime,
      };
    }
  }

  /**
   * S-expression 실행
   */
  executeSExpression(expr) {
    // 기본 변수 선언: (define name value)
    const defineMatch = expr.match(/^\(define\s+(\w+)\s+(.+)\)$/);
    if (defineMatch) {
      const [, name, valueExpr] = defineMatch;
      this.lastResult = this.evaluateExpression(valueExpr);
      this.scope.set(name, this.lastResult);
      return;
    }

    // 함수 호출: (call function arg1 arg2 ...)
    const callMatch = expr.match(/^\(call\s+(\S+)\s*(.*)\)$/);
    if (callMatch) {
      const [, funcName, argsStr] = callMatch;
      this.lastResult = this.executeFunction(funcName, argsStr);
      return;
    }

    // if 조건: (if condition then-block else-block)
    const ifMatch = expr.match(/^\(if\s+(.+?)\s+\(do\s+(.+?)\)\s+\(do\s+(.+?)\)\)$/);
    if (ifMatch) {
      const [, condExpr, thenExpr, elseExpr] = ifMatch;
      const condition = this.evaluateExpression(condExpr);
      if (condition) {
        this.executeSExpression(thenExpr);
      } else {
        this.executeSExpression(elseExpr);
      }
      return;
    }

    // for 루프: (for iterator range body)
    const forMatch = expr.match(/^\(for\s+(\w+)\s+\(array\s+([\d\s]+)\)\s+\(do\s+(.+?)\)\)$/);
    if (forMatch) {
      const [, iterator, elementsStr, bodyExpr] = forMatch;
      const elements = elementsStr.trim().split(/\s+/).map(e => Number(e));
      for (const elem of elements) {
        this.scope.set(iterator, elem);
        this.executeSExpression(bodyExpr);
      }
      return;
    }
  }

  /**
   * 식 평가
   */
  evaluateExpression(expr) {
    expr = expr.trim();

    // 문자열 리터럴
    if (expr.startsWith('"') && expr.endsWith('"')) {
      return expr.slice(1, -1);
    }

    // 숫자 리터럴
    if (!isNaN(Number(expr))) {
      return Number(expr);
    }

    // 참조 (변수명)
    if (this.scope.has(expr)) {
      return this.scope.get(expr);
    }

    // 배열: (array elem1 elem2 ...)
    if (expr.startsWith('(array')) {
      const elementsStr = expr.slice(7, -1).trim();
      if (!elementsStr) return [];
      return elementsStr.split(/\s+/).map(e => this.evaluateExpression(e));
    }

    // 객체: (object (key1 val1) (key2 val2) ...)
    if (expr.startsWith('(object')) {
      const obj = {};
      const propsStr = expr.slice(8, -1);
      const propMatches = propsStr.match(/\("(\w+)"\s+([^)]+)\)/g);
      if (propMatches) {
        propMatches.forEach(prop => {
          const match = prop.match(/\("(\w+)"\s+(.+)\)/);
          if (match) {
            obj[match[1]] = this.evaluateExpression(match[2]);
          }
        });
      }
      return obj;
    }

    // 산술 연산: (+ a b), (- a b), (* a b), (/ a b), (% a b)
    const arithmeticMatch = expr.match(/^\(([+\-*/%])\s+(.+?)\s+(.+)\)$/);
    if (arithmeticMatch) {
      const [, op, left, right] = arithmeticMatch;
      const leftVal = this.evaluateExpression(left);
      const rightVal = this.evaluateExpression(right);
      switch (op) {
        case '+': return leftVal + rightVal;
        case '-': return leftVal - rightVal;
        case '*': return leftVal * rightVal;
        case '/': return leftVal / rightVal;
        case '%': return leftVal % rightVal;
      }
    }

    // 비교 연산: (== a b), (!= a b), (< a b), (> a b), (<= a b), (>= a b)
    const comparisonMatch = expr.match(/^\((==|!=|<|>|<=|>=)\s+(.+?)\s+(.+)\)$/);
    if (comparisonMatch) {
      const [, op, left, right] = comparisonMatch;
      const leftVal = this.evaluateExpression(left);
      const rightVal = this.evaluateExpression(right);
      switch (op) {
        case '==': return leftVal === rightVal;
        case '!=': return leftVal !== rightVal;
        case '<': return leftVal < rightVal;
        case '>': return leftVal > rightVal;
        case '<=': return leftVal <= rightVal;
        case '>=': return leftVal >= rightVal;
      }
    }

    // 함수: (fn (params) body)
    if (expr.startsWith('(fn')) {
      // 람다 함수 반환 (실제 평가는 나중에)
      return { type: 'lambda', expr: expr };
    }

    return null;
  }

  /**
   * 함수 실행
   */
  executeFunction(funcName, argsStr) {
    const args = this.parseArguments(argsStr);

    switch (funcName) {
      case 'print':
        if (args.length > 0) {
          this.output.push(String(args[0]));
        }
        return args[0];

      case 'IO.print_array':
        if (args.length > 0 && Array.isArray(args[0])) {
          const result = args[0];
          this.output.push(JSON.stringify(result));
          return result;
        }
        return null;

      case 'Array.map': {
        if (args.length >= 2 && Array.isArray(args[0]) && args[1].type === 'lambda') {
          const array = args[0];
          const lambdaExpr = args[1].expr;

          // 람다 파라미터 추출: (fn (param) body)
          const paramMatch = lambdaExpr.match(/\(fn\s+\((\w+)\)\s+(.+)\)/);
          if (paramMatch) {
            const [, paramName, bodyExpr] = paramMatch;
            const result = [];
            for (const elem of array) {
              this.scope.set(paramName, elem);
              result.push(this.evaluateExpression(bodyExpr));
            }
            return result;
          }
        }
        return args[0];
      }

      case 'Array.filter': {
        if (args.length >= 2 && Array.isArray(args[0]) && args[1].type === 'lambda') {
          const array = args[0];
          const lambdaExpr = args[1].expr;

          const paramMatch = lambdaExpr.match(/\(fn\s+\((\w+)\)\s+(.+)\)/);
          if (paramMatch) {
            const [, paramName, bodyExpr] = paramMatch;
            const result = [];
            for (const elem of array) {
              this.scope.set(paramName, elem);
              if (this.evaluateExpression(bodyExpr)) {
                result.push(elem);
              }
            }
            return result;
          }
        }
        return args[0];
      }

      case 'Array.reduce': {
        if (args.length >= 3 && Array.isArray(args[0]) && args[1].type === 'lambda') {
          const array = args[0];
          const lambdaExpr = args[1].expr;
          let accumulator = args[2];

          const paramMatch = lambdaExpr.match(/\(fn\s+\((\w+)\s+(\w+)\)\s+(.+)\)/);
          if (paramMatch) {
            const [, accName, elemName, bodyExpr] = paramMatch;
            for (const elem of array) {
              this.scope.set(accName, accumulator);
              this.scope.set(elemName, elem);
              accumulator = this.evaluateExpression(bodyExpr);
            }
            return accumulator;
          }
        }
        return args[2];
      }

      case 'String.split': {
        if (args.length >= 2 && typeof args[0] === 'string' && typeof args[1] === 'string') {
          return args[0].split(args[1]);
        }
        return args[0];
      }

      case 'String.join': {
        if (args.length >= 2 && Array.isArray(args[0]) && typeof args[1] === 'string') {
          return args[0].join(args[1]);
        }
        return '';
      }

      case 'String.upper': {
        if (args.length >= 1 && typeof args[0] === 'string') {
          return args[0].toUpperCase();
        }
        return args[0];
      }

      case 'String.lower': {
        if (args.length >= 1 && typeof args[0] === 'string') {
          return args[0].toLowerCase();
        }
        return args[0];
      }

      case 'String.trim': {
        if (args.length >= 1 && typeof args[0] === 'string') {
          return args[0].trim();
        }
        return args[0];
      }

      case 'Math.sqrt':
        return Math.sqrt(Number(args[0]));

      case 'Math.pow':
        return Math.pow(Number(args[0]), Number(args[1]));

      case 'Math.abs':
        return Math.abs(Number(args[0]));

      case 'Array.find': {
        if (args.length >= 2 && Array.isArray(args[0]) && args[1].type === 'lambda') {
          const array = args[0];
          const lambdaExpr = args[1].expr;

          const paramMatch = lambdaExpr.match(/\(fn\s+\((\w+)\)\s+(.+)\)/);
          if (paramMatch) {
            const [, paramName, bodyExpr] = paramMatch;
            for (const elem of array) {
              this.scope.set(paramName, elem);
              if (this.evaluateExpression(bodyExpr)) {
                return elem;
              }
            }
          }
        }
        return null;
      }

      case 'JSON.stringify':
        return JSON.stringify(args[0]);

      case 'JSON.parse':
        try {
          return JSON.parse(args[0]);
        } catch {
          return null;
        }

      default:
        this.output.push(`[${funcName}] 함수 호출`);
        return null;
    }
  }

  /**
   * 인수 파싱
   */
  parseArguments(argsStr) {
    if (!argsStr.trim()) return [];

    const args = [];
    let current = '';
    let depth = 0;
    let inQuotes = false;

    for (const char of argsStr) {
      if (char === '"') {
        inQuotes = !inQuotes;
        current += char;
      } else if (char === '(' && !inQuotes) {
        depth++;
        current += char;
      } else if (char === ')' && !inQuotes) {
        depth--;
        current += char;
      } else if (char === ' ' && !inQuotes && depth === 0) {
        if (current) args.push(current);
        current = '';
      } else {
        current += char;
      }
    }
    if (current) args.push(current);

    return args.map(arg => this.evaluateExpression(arg));
  }
}

/**
 * CLAUDELang 메인 클래스
 * JSON 파일 읽기 → 컴파일 → 실행 → 결과 반환
 */
class CLAUDELang {
  constructor() {
    this.compiler = new CLAUDELangCompiler();
    this.runtime = new VTRuntime();
  }

  /**
   * 파일 실행
   */
  runFile(jsonFilePath) {
    try {
      // 1. JSON 파일 읽기
      const fileContent = fs.readFileSync(jsonFilePath, 'utf-8');
      const program = JSON.parse(fileContent);

      // 2. 컴파일
      const compileResult = this.compiler.compile(program);
      if (!compileResult.success) {
        return {
          success: false,
          error: `Compilation failed: ${compileResult.errors.join(', ')}`,
        };
      }

      // 3. VT 런타임에서 실행
      this.runtime = new VTRuntime(); // 런타임 초기화
      const executionResult = this.runtime.execute(compileResult.code);

      // 4. 결과 반환
      return {
        success: executionResult.success,
        output: executionResult.output,
        result: executionResult.result,
        executionTime: executionResult.executionTime,
        memoryUsage: executionResult.memoryUsage,
        instructionCount: executionResult.instructionCount,
        error: executionResult.error,
      };
    } catch (error) {
      return {
        success: false,
        error: error.message,
      };
    }
  }

  /**
   * 프로그램 문자열 실행
   */
  runProgram(program) {
    try {
      // 1. 컴파일
      const compileResult = this.compiler.compile(program);
      if (!compileResult.success) {
        return {
          success: false,
          error: `Compilation failed: ${compileResult.errors.join(', ')}`,
        };
      }

      // 2. 실행
      this.runtime = new VTRuntime();
      const executionResult = this.runtime.execute(compileResult.code);

      return {
        success: executionResult.success,
        output: executionResult.output,
        result: executionResult.result,
        executionTime: executionResult.executionTime,
        memoryUsage: executionResult.memoryUsage,
        instructionCount: executionResult.instructionCount,
        error: executionResult.error,
      };
    } catch (error) {
      return {
        success: false,
        error: error.message,
      };
    }
  }

  /**
   * 예제 디렉토리의 모든 파일 실행
   */
  runExamplesDirectory(examplesDir) {
    const results = {};
    const files = fs.readdirSync(examplesDir)
      .filter(f => f.endsWith('.json'))
      .sort();

    for (const file of files) {
      const filePath = path.join(examplesDir, file);
      const name = path.basename(file, '.json');
      results[name] = this.runFile(filePath);
    }

    return results;
  }
}

