// KPM API Configuration
module.exports = {
  // 로컬 서버 (기본값)
  // baseUrl: 'http://localhost:4000/api',

  // 253 서버 (원격)
  baseUrl: 'http://123.212.111.26:4000/api',

  // 인증 타입
  authType: 'Custom',

  // 타임아웃
  timeout: 30000,

  // SSL 검증
  rejectUnauthorized: false
};
'use strict';

const homedir = require('os').homedir;
const resolve = require('path').resolve;
const request = require('request');
const curry = require('lodash').curry;
const retrieve = require('./credentials').retrieve;
const cbPromiseHandler = require('./util').cbPromiseHandler;
const config = require('./api-config');

const kpmrcPath = resolve(homedir(), '.kpmrc'); // todo: move this to start

function post(params, fn) {
  return makeRequest(params, request.post, fn);
}

function put(params, fn) {
  return makeRequest(params, request.put, fn);
}

function makeRequest(params, methodFn, fn) {
  // todo: prepend base url
  // todo: inject authorization
  // todo: handle common errors

  if (typeof params !== 'object') {
    params = { url: params };
  }
  // Prepend base URL from configuration (supports both localhost and remote server)
  params.url = `${config.baseUrl}${params.url}`;
  params.json = true;

  const auth = retrieve(kpmrcPath);
  if (auth) {
    params.headers = {
      authorization: `Custom ${auth}`
    };
  }

  return methodFn.call(methodFn, params, fn);
}

module.exports = {
  handler: cbPromiseHandler,
  post,
  put
};
'use strict';

const createReadStream = require('fs').createReadStream;
const curry = require('lodash').curry;
const put = require('./api').put;
const cbPromiseHandler = require('./util').cbPromiseHandler;

// uploads the archive at the path as the plugin version
// must reject if user is not owner
// must reject if archive already exists
// must reject if version does not exist
function uploadFile(path, version) {
  const archiveUrl = url(version.url);
  return new Promise((resolve, reject) => {
    const stream = put(archiveUrl, cbPromiseHandler(resolve, reject));
    createReadStream(path).pipe(stream);
    // todo: pass application/x-gzip ?
  })
  .then(response => {
    if (response.statusCode !== 204) {
      throw new Error(`Unexpected status: ${response.statusCode}`);
    }
    return { url: archiveUrl };
  });
}

function url(versionUrl) {
  return `${versionUrl}/archive`;
}

module.exports = {
  uploadFile: curry(uploadFile),
  url
};
'use strict';

