const http = require('http');
const fs = require('fs');
const path = require('path');
const url = require('url');

const REGISTRY_FILE = '/home/kimjin/kpm-registry/registry.json';

// Load registry
let registry = {};
try {
  if (fs.existsSync(REGISTRY_FILE)) {
    registry = JSON.parse(fs.readFileSync(REGISTRY_FILE, 'utf-8'));
  }
} catch (e) {
  console.error('Error loading registry:', e);
  registry = {};
}

const server = http.createServer((req, res) => {
  const parsedUrl = url.parse(req.url, true);
  const pathname = parsedUrl.pathname;

  res.setHeader('Content-Type', 'application/json');
  res.setHeader('Access-Control-Allow-Origin', '*');

  // Health check
  if (pathname === '/api/ping') {
    res.writeHead(200);
    res.end(JSON.stringify({ status: 'ok', timestamp: new Date() }));
    return;
  }

  // Upload plugin metadata
  if (pathname === '/api/plugin' && req.method === 'PUT') {
    let body = '';
    req.on('data', chunk => { body += chunk; });
    req.on('end', () => {
      try {
        const plugin = JSON.parse(body);
        registry[plugin.name] = plugin;
        fs.writeFileSync(REGISTRY_FILE, JSON.stringify(registry, null, 2));
        res.writeHead(201);
        res.end(JSON.stringify({ success: true, plugin: plugin.name }));
      } catch (e) {
        res.writeHead(400);
        res.end(JSON.stringify({ error: e.message }));
      }
    });
    return;
  }

