   638→/**
   639→ * VT Runtime Bridge - 메인 인터페이스
   640→ */
   641→class VTRuntimeBridge {
   642→  constructor() {
   643→    this.evaluator = new VTEvaluator();
   644→  }
   645→
   646→  /**
   647→   * VT 코드 실행
   648→   * @param {string} vtCode - VT 코드 (스킴 형식)
   649→   * @returns {Object} {success, result, memory, errors}
   650→   */
   651→  execute(vtCode) {
   652→    try {
   653→      // 1. 토크나이즈
   654→      const tokenizer = new VTTokenizer(vtCode);
   655→      const tokens = tokenizer.tokenize();
   656→
   657→      // 2. 파싱
   658→      const parser = new VTParser(tokens);
   659→      const ast = parser.parse();
   660→
   661→      // 3. 평가
   662→      const result = this.evaluator.evaluate(ast);
   663→
   664→      // 4. 메모리 상태 반환
   665→      return {
   666→        success: true,
   667→        result: result,
   668→        memory: this.evaluator.getMemory(),
   669→        errors: []
   670→      };
   671→    } catch (error) {
   672→      return {
   673→        success: false,
   674→        result: null,
   675→        memory: this.evaluator.getMemory(),
   676→        errors: [error.message]
   677→      };
   678→    }
   679→  }
   680→
   681→  /**
   682→   * 메모리 상태 조회
   683→   */
   684→  getMemory() {
   685→    return this.evaluator.getMemory();
   686→  }
   687→
   688→  /**
   689→   * 메모리 초기화
   690→   */
   691→  clearMemory() {
   692→    this.evaluator.clearMemory();
   693→  }
   694→
   695→  /**
   696→   * 함수 등록
   697→   */
   698→  registerFunction(name, fn) {
   699→    this.evaluator.registerFunction(name, fn);
   700→  }
   701→
   702→  /**
   703→   * CLAUDELang JSON + 컴파일러를 사용하여 직접 실행
   704→   * @param {Object} claudelangJson - CLAUDELang JSON
   705→   * @param {CLAUDELangCompiler} compiler - 컴파일러 인스턴스
   706→   * @returns {Object} 실행 결과
   707→   */
   708→  executeJSON(claudelangJson, compiler) {
   709→    try {
   710→      // 컴파일
   711→      const compiled = compiler.compile(claudelangJson);
   712→      if (!compiled.success) {
   713→        return {
   714→          success: false,
   715→          result: null,
   716→          memory: {},
   717→          errors: compiled.errors
   718→        };
   719→      }
   720→
   721→      // 실행
   722→      return this.execute(compiled.code);
   723→    } catch (error) {
   724→      return {
   725→        success: false,
   726→        result: null,
   727→        memory: {},
   728→        errors: [error.message]
   729→      };
   730→    }
   731→  }
   732→}
   733→
   734→// 내보내기
   735→if (typeof module !== 'undefined' && module.exports) {
   736→  module.exports = {
   737→    VTTokenizer,
   738→    VTParser,
   739→    VTEvaluator,
   740→    VTRuntimeBridge
   741→  };
   742→}
