     1→/**
     2→ * VT Runtime Bridge - 통합 테스트
     3→ * 모든 예제 파일에 대한 테스트
     4→ */
     5→
     6→const fs = require('fs');
     7→const path = require('path');
     8→const CLAUDELangCompiler = require('../src/compiler');
     9→const { VTRuntimeBridge } = require('../src/vt-runtime-bridge');
    10→
    11→// 색상 출력
    12→const colors = {
    13→  reset: '\x1b[0m',
    14→  green: '\x1b[32m',
    15→  red: '\x1b[31m',
    16→  yellow: '\x1b[33m',
    17→  blue: '\x1b[34m',
    18→  cyan: '\x1b[36m'
    19→};
    20→
    21→function log(color, text) {
    22→  console.log(`${colors[color]}${text}${colors.reset}`);
    23→}
    24→
    25→class TestRunner {
    26→  constructor() {
    27→    this.compiler = new CLAUDELangCompiler();
    28→    this.bridge = new VTRuntimeBridge();
    29→    this.testCount = 0;
    30→    this.passCount = 0;
    31→    this.failCount = 0;
    32→    this.results = [];
    33→  }
    34→
    35→  /**
    36→   * 단일 테스트 실행
    37→   */
    38→  runTest(name, jsonPath, expectedBehavior = null) {
    39→    this.testCount++;
    40→    const relPath = path.relative(process.cwd(), jsonPath);
    41→
    42→    try {
    43→      // JSON 파일 읽기
    44→      const content = fs.readFileSync(jsonPath, 'utf8');
    45→      const json = JSON.parse(content);
    46→
    47→      // 컴파일
    48→      const compiled = this.compiler.compile(json);
    49→
    50→      if (!compiled.success) {
    51→        log('red', `✗ ${name}`);
    52→        log('red', `  Compilation failed: ${compiled.errors.join(', ')}`);
    53→        this.failCount++;
    54→        this.results.push({
    55→          name,
    56→          status: 'FAILED',
    57→          reason: `Compilation: ${compiled.errors[0]}`
    58→        });
    59→        return;
    60→      }
    61→
    62→      // 실행
    63→      const result = this.bridge.execute(compiled.code);
    64→
    65→      if (!result.success) {
    66→        log('red', `✗ ${name}`);
    67→        log('red', `  Execution failed: ${result.errors.join(', ')}`);
    68→        this.failCount++;
    69→        this.results.push({
    70→          name,
    71→          status: 'FAILED',
    72→          reason: `Execution: ${result.errors[0]}`
    73→        });
    74→        return;
    75→      }
    76→
    77→      // 성공
    78→      log('green', `✓ ${name}`);
    79→      this.passCount++;
    80→      this.results.push({
    81→        name,
    82→        status: 'PASSED',
    83→        result: result.result,
    84→        memory: result.memory
    85→      });
    86→
    87→      // 메모리 초기화
    88→      this.bridge.clearMemory();
    89→    } catch (error) {
    90→      log('red', `✗ ${name}`);
    91→      log('red', `  Error: ${error.message}`);
    92→      this.failCount++;
    93→      this.results.push({
    94→        name,
    95→        status: 'ERROR',
    96→        reason: error.message
    97→      });
    98→    }
    99→  }
   100→
   101→  /**
   102→   * 모든 테스트 실행
   103→   */
   104→  runAll() {
   105→    const examplesDir = path.join(__dirname, '..', 'examples');
   106→
   107→    log('cyan', '\n╔════════════════════════════════════════════╗');
   108→    log('cyan', '║  CLAUDELang v6.0 - VT Runtime Tests      ║');
   109→    log('cyan', '╚════════════════════════════════════════════╝\n');
   110→
   111→    // 예제 파일 찾기
   112→    const files = fs.readdirSync(examplesDir)
   113→      .filter(f => f.endsWith('.json'))
   114→      .sort();
   115→
   116→    log('blue', `Found ${files.length} test files\n`);
   117→
   118→    // 각 파일 실행
   119→    files.forEach(file => {
   120→      const filepath = path.join(examplesDir, file);
   121→      const testName = file.replace('.json', '');
   122→      this.runTest(testName, filepath);
   123→    });
   124→
   125→    // 결과 요약
   126→    this.printSummary();
   127→  }
   128→
   129→  /**
   130→   * 결과 요약 출력
   131→   */
   132→  printSummary() {
   133→    log('cyan', '\n╔════════════════════════════════════════════╗');
   134→    log('cyan', '║           Test Summary                     ║');
   135→    log('cyan', '╚════════════════════════════════════════════╝\n');
   136→
   137→    log('blue', `Total Tests: ${this.testCount}`);
   138→    log('green', `Passed: ${this.passCount}`);
   139→    if (this.failCount > 0) {
   140→      log('red', `Failed: ${this.failCount}`);
   141→    }
   142→
   143→    const passRate = this.testCount > 0 ? (this.passCount / this.testCount * 100).toFixed(1) : 0;
   144→    log('blue', `Pass Rate: ${passRate}%\n`);
   145→
   146→    // 실패 테스트 상세 출력
   147→    if (this.failCount > 0) {
   148→      log('yellow', '━━━ Failed Tests ━━━');
   149→      this.results
   150→        .filter(r => r.status !== 'PASSED')
   151→        .forEach(r => {
   152→          log('red', `• ${r.name}`);
   153→          log('red', `  Status: ${r.status}`);
   154→          log('red', `  Reason: ${r.reason || 'Unknown error'}`);
   155→        });
   156→      log('yellow', '');
   157→    }
   158→
   159→    // 전체 결과 정보
   160→    if (this.passCount > 0) {
   161→      log('green', '━━━ Test Details ━━━');
   162→      this.results
   163→        .filter(r => r.status === 'PASSED')
   164→        .slice(0, 5) // 처음 5개만 표시
   165→        .forEach(r => {
   166→          log('green', `• ${r.name}`);
   167→          if (r.result !== null && r.result !== undefined) {
   168→            log('cyan', `  Result: ${JSON.stringify(r.result).substring(0, 50)}...`);
   169→          }
   170→        });
   171→
   172→      if (this.passCount > 5) {
   173→        log('cyan', `  ... and ${this.passCount - 5} more passed tests`);
   174→      }
   175→      log('cyan', '');
   176→    }
   177→
   178→    return {
   179→      total: this.testCount,
   180→      passed: this.passCount,
   181→      failed: this.failCount,
   182→      passRate: parseFloat(passRate)
   183→    };
   184→  }
   185→}
   186→
   187→// 테스트 실행
   188→if (require.main === module) {
   189→  const runner = new TestRunner();
   190→  runner.runAll();
   191→
   192→  // 프로세스 종료 코드
   193→  process.exit(runner.failCount > 0 ? 1 : 0);
   194→}
   195→
   196→module.exports = TestRunner;
   197→

