/**
 * VT Runtime Bridge for CLAUDELang v6.0
 * VT 코드 (스킴 형식) → AST → 실행
 *
 * 역할:
 * 1. VT 코드 파싱 (스킴 형식)
 * 2. AST 생성
 * 3. 런타임 평가
 * 4. 메모리 관리
 * 5. 함수 호출
 */

'use strict';

/**
 * VT 코드를 토큰으로 변환
 */
class VTTokenizer {
  constructor(code) {
    this.code = code;
    this.pos = 0;
    this.tokens = [];
  }

  tokenize() {
    while (this.pos < this.code.length) {
      const char = this.code[this.pos];

      // 공백 무시
      if (/\s/.test(char)) {
        this.pos++;
        continue;
      }

      // 주석 무시
      if (char === ';') {
        while (this.pos < this.code.length && this.code[this.pos] !== '\n') {
          this.pos++;
        }
        continue;
      }

      // 괄호
      if (char === '(' || char === ')') {
        this.tokens.push(char);
        this.pos++;
        continue;
      }

      // 문자열
      if (char === '"') {
        const str = this.readString();
        this.tokens.push({ type: 'string', value: str });
        continue;
      }

      // 심볼/숫자
      const symbol = this.readSymbol();
      if (symbol) {
        // 숫자인지 확인
        if (/^-?\d+(\.\d+)?$/.test(symbol)) {
          this.tokens.push({ type: 'number', value: parseFloat(symbol) });
        } else if (symbol === 'true' || symbol === 'false') {
          this.tokens.push({ type: 'boolean', value: symbol === 'true' });
        } else {
          this.tokens.push({ type: 'symbol', value: symbol });
        }
      }
    }

    return this.tokens;
  }

  readString() {
    this.pos++; // 시작 따옴표 건너뛰기
    let str = '';
    while (this.pos < this.code.length && this.code[this.pos] !== '"') {
      if (this.code[this.pos] === '\\') {
        this.pos++;
        if (this.pos < this.code.length) {
          switch (this.code[this.pos]) {
            case 'n': str += '\n'; break;
            case 't': str += '\t'; break;
            case 'r': str += '\r'; break;
            case '"': str += '"'; break;
            case '\\': str += '\\'; break;
            default: str += this.code[this.pos];
          }
          this.pos++;
        }
      } else {
        str += this.code[this.pos];
        this.pos++;
      }
    }
    this.pos++; // 끝 따옴표 건너뛰기
    return str;
  }

  readSymbol() {
    let symbol = '';
    while (this.pos < this.code.length && !/[\s()"]/.test(this.code[this.pos])) {
      symbol += this.code[this.pos];
      this.pos++;
    }
    return symbol;
  }
}

/**
 * VT 토큰을 AST로 파싱
 */
class VTParser {
  constructor(tokens) {
    this.tokens = tokens;
    this.pos = 0;
  }

  parse() {
    const expressions = [];
    while (this.pos < this.tokens.length) {
      const expr = this.parseExpression();
      if (expr !== null) {
        expressions.push(expr);
      }
    }
    return { type: 'program', expressions };
  }

  parseExpression() {
    const token = this.peek();
    if (token === null) return null;

    if (token === '(') {
      return this.parseList();
    } else {
      return this.parseAtom();
    }
  }

  parseList() {
    this.consume('(');
    const elements = [];
    while (this.peek() !== ')') {
      elements.push(this.parseExpression());
    }
    this.consume(')');
    return { type: 'list', elements };
  }

  parseAtom() {
    const token = this.next();
    if (token === null) return null;

    if (typeof token === 'object') {
      return {
        type: 'literal',
        value: token.value,
        literalType: token.type
      };
    } else {
      return {
        type: 'symbol',
        value: token
      };
    }
  }

  peek() {
    if (this.pos < this.tokens.length) {
      return this.tokens[this.pos];
    }
    return null;
  }

  next() {
    if (this.pos < this.tokens.length) {
      return this.tokens[this.pos++];
    }
    return null;
  }

  consume(expected) {
    const token = this.next();
    if (token !== expected) {
      throw new Error(`Expected '${expected}', got '${token}'`);
    }
  }
}

/**
 * VT AST를 평가하는 평가기
 */
class VTEvaluator {
  constructor() {
    // 스코프 체인 시스템 (배열의 0번 인덱스가 전역 스코프)
    this.scopes = [new Map()];
    this.functions = new Map();
    this.initializeBuiltins();
  }

  /**
   * 변수 조회 (현재 스코프에서 전역 스코프로 탐색)
   */
  lookupVar(name) {
    // 스택 최상단에서 최하단(전역)으로 탐색
    for (let i = this.scopes.length - 1; i >= 0; i--) {
      if (this.scopes[i].has(name)) {
        return this.scopes[i].get(name);
      }
    }
    throw new Error(`Undefined variable: ${name}`);
  }

  /**
   * 변수 설정 (가장 가까운 스코프에 설정)
   */
  setVar(name, value) {
    this.scopes[this.scopes.length - 1].set(name, value);
  }

  /**
   * 변수 존재 확인
   */
  hasVar(name) {
    for (let i = this.scopes.length - 1; i >= 0; i--) {
      if (this.scopes[i].has(name)) {
        return true;
      }
    }
    return false;
  }

  /**
   * 새 스코프 푸시
   */
  pushScope() {
    this.scopes.push(new Map());
  }

  /**
   * 현재 스코프 팝
   */
  popScope() {
    if (this.scopes.length > 1) {
      this.scopes.pop();
