  initializeBuiltins() {
    // I/O
    this.functions.set('print', (value) => {
      process.stdout.write(String(value));
      return null;
    });

    this.functions.set('println', (value) => {
      console.log(String(value));
      return null;
    });

    // 산술 연산
    this.functions.set('+', (...args) => {
      return args.reduce((a, b) => a + b, 0);
