    this.functions.set('-', (...args) => {
      if (args.length === 1) return -args[0];
      return args.reduce((a, b) => a - b);
    });

    this.functions.set('*', (...args) => {
      return args.reduce((a, b) => a * b, 1);
    });

    this.functions.set('/', (...args) => {
      return args.reduce((a, b) => a / b);
    });

    this.functions.set('%', (a, b) => {
