  evaluateExpression(expr) {
    if (!expr) return null;

    switch (expr.type) {
      case 'literal':
        return expr.value;

      case 'symbol':
        // 변수 참조 (스코프 체인 탐색)
        return this.lookupVar(expr.value);

      case 'list':
        return this.evaluateList(expr);

      default:
        return null;
    }
