/**
 * VT Runtime Bridge - 통합 테스트
 * 모든 예제 파일에 대한 테스트
 */

const fs = require('fs');
const path = require('path');
const CLAUDELangCompiler = require('../src/compiler');
const { VTRuntimeBridge } = require('../src/vt-runtime-bridge');

// 색상 출력
const colors = {
  reset: '\x1b[0m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  cyan: '\x1b[36m'
};

function log(color, text) {
  console.log(`${colors[color]}${text}${colors.reset}`);
}

class TestRunner {
  constructor() {
    this.compiler = new CLAUDELangCompiler();
    this.bridge = new VTRuntimeBridge();
    this.testCount = 0;
    this.passCount = 0;
    this.failCount = 0;
    this.results = [];
  }

  /**
   * 단일 테스트 실행
   */
  runTest(name, jsonPath, expectedBehavior = null) {
    this.testCount++;
    const relPath = path.relative(process.cwd(), jsonPath);

    try {
      // JSON 파일 읽기
      const content = fs.readFileSync(jsonPath, 'utf8');
      const json = JSON.parse(content);

      // 컴파일
      const compiled = this.compiler.compile(json);

      if (!compiled.success) {
        log('red', `✗ ${name}`);
        log('red', `  Compilation failed: ${compiled.errors.join(', ')}`);
        this.failCount++;
        this.results.push({
          name,
          status: 'FAILED',
          reason: `Compilation: ${compiled.errors[0]}`
        });
        return;
      }

      // 실행
      const result = this.bridge.execute(compiled.code);

      if (!result.success) {
        log('red', `✗ ${name}`);
        log('red', `  Execution failed: ${result.errors.join(', ')}`);
        this.failCount++;
        this.results.push({
          name,
          status: 'FAILED',
          reason: `Execution: ${result.errors[0]}`
        });
        return;
      }

      // 성공
      log('green', `✓ ${name}`);
      this.passCount++;
      this.results.push({
        name,
        status: 'PASSED',
        result: result.result,
        memory: result.memory
      });

      // 메모리 초기화
      this.bridge.clearMemory();
    } catch (error) {
      log('red', `✗ ${name}`);
      log('red', `  Error: ${error.message}`);
      this.failCount++;
      this.results.push({
        name,
        status: 'ERROR',
        reason: error.message
      });
    }
  }

