 */
runProgram(program, baseDir = process.cwd(), debugMode = null) {
  try {
    // debugMode가 null이면 인스턴스 설정 사용
    const enableDebug = debugMode !== null ? debugMode : this.debugMode;

    // 1. 바이트코드 캐시 확인
    const programHash = this.hashProgram(program);
    let vtCode;
