    });

    const totalTime = this.results.reduce((sum, r) => sum + r.avgTime, 0);
    const totalMemory = this.results.reduce((sum, r) => sum + r.avgMemory, 0);

    console.log('\n📈 Overall Statistics:');
    console.log('─'.repeat(60));
