    console.log(`Total Memory: ${totalMemory.toFixed(2)}MB`);
    console.log(`Avg Time: ${(totalTime / this.results.length).toFixed(2)}ms`);
    console.log(`Avg Memory: ${(totalMemory / this.results.length).toFixed(2)}MB`);
  }
}

