// AST 검증기 간단한 버전
class ASTValidator {
  constructor() {
    this.errors = [];
  }

  validateProgram(data) {
    this.errors = [];

    if (!data || typeof data !== 'object') {
      this.errors.push('프로그램은 객체여야 합니다');
      return { valid: false, errors: this.errors };
    }

    if (data.type !== 'program') {
      this.errors.push(`type은 "program"이어야 합니다. 받은 값: ${data.type}`);
    }

    if (!data.version) {
      this.errors.push('version은 필수입니다');
    }

    if (!Array.isArray(data.definitions)) {
      this.errors.push('definitions은 배열이어야 합니다');
    } else {
      data.definitions.forEach((def, i) => {
        if (def.type === 'function') {
          if (!def.name) this.errors.push(`definitions[${i}]: name이 없습니다`);
          if (!def.params || !Array.isArray(def.params)) 
            this.errors.push(`definitions[${i}]: params는 배열이어야 합니다`);
          if (!def.return_type) 
            this.errors.push(`definitions[${i}]: return_type이 없습니다`);
          if (!Array.isArray(def.body)) 
            this.errors.push(`definitions[${i}]: body는 배열이어야 합니다`);
        }
      });
    }

    if (!Array.isArray(data.instructions)) {
      this.errors.push('instructions는 배열이어야 합니다');
    }

    return {
      valid: this.errors.length === 0,
      errors: this.errors,
      ast: this.errors.length === 0 ? data : null
    };
  }
}

// 파일 읽기
