     1→/**
     2→ * ClaudeScript 타입 검사기
     3→ * AST의 타입 안전성을 검증합니다
     4→ */
     5→
     6→import {
     7→  Program,
     8→  Statement,
     9→  Expression,
    10→  TypeSpec,
    11→  TypeCheckResult,
    12→  ValidationError,
    13→  FunctionDef,
    14→} from "./ast";
    15→
    16→type TypeInfo = {
    17→  [name: string]: TypeSpec;
    18→};
    19→
    20→interface FunctionInfo {
    21→  [name: string]: {
    22→    params: Array<{ name: string; type: TypeSpec }>;
    23→    return_type: TypeSpec;
    24→  };
    25→}
    26→
    27→export class TypeChecker {
    28→  private errors: ValidationError[] = [];
    29→  private variables: TypeInfo = {};
    30→  private functions: FunctionInfo = {};
    31→  private scopes: Array<TypeInfo> = [];
    32→
    33→  /**
    34→   * 프로그램 전체 타입 검사
    35→   */
    36→  checkProgram(ast: Program): TypeCheckResult {
    37→    this.errors = [];
    38→    this.variables = {};
    39→    this.functions = {};
    40→    this.scopes = [{}];  // 전역 스코프
    41→
    42→    // 1단계: 함수 정의 수집
    43→    this.collectFunctionDefinitions(ast.definitions);
    44→
    45→    // 2단계: 함수 본체 검사
    46→    for (const def of ast.definitions) {
    47→      this.checkFunctionDef(def);
    48→    }
    49→
    50→    // 3단계: 실행 명령 검사
    51→    for (let i = 0; i < ast.instructions.length; i++) {
    52→      this.checkStatement(ast.instructions[i], i);
    53→    }
    54→
    55→    const typeInfoMap = new Map<string, TypeSpec>(Object.entries(this.variables));
    56→    return {
    57→      valid: this.errors.length === 0,
    58→      errors: this.errors,
    59→      typeInfo: typeInfoMap,
    60→    };
    61→  }
    62→
    63→  /**
    64→   * 함수 정의 수집 (선언-사용 순서 보장)
    65→   */
    66→  private collectFunctionDefinitions(definitions: FunctionDef[]) {
    67→    for (const def of definitions) {
    68→      this.functions[def.name] = {
    69→        params: def.params,
    70→        return_type: def.return_type,
    71→      };
    72→    }
    73→  }
    74→
    75→  /**
    76→   * 함수 정의 검사
    77→   */
    78→  private checkFunctionDef(def: FunctionDef) {
    79→    // 함수 파라미터를 함수 스코프에 추가
    80→    const funcScope: TypeInfo = {};
    81→    for (const param of def.params) {
    82→      funcScope[param.name] = param.type;
    83→    }
    84→
    85→    // 이전 스코프 저장
    86→    const prevScope = this.scopes[this.scopes.length - 1];
    87→    this.scopes[this.scopes.length - 1] = funcScope;
    88→
    89→    // 함수 본체 검사
    90→    for (let i = 0; i < def.body.length; i++) {
    91→      this.checkStatement(def.body[i], i, `function ${def.name}`);
    92→    }
    93→
    94→    // 스코프 복원
    95→    this.scopes[this.scopes.length - 1] = prevScope;
    96→  }
    97→
    98→  /**
    99→   * 문장 검사
   100→   */
   101→  private checkStatement(stmt: any, index: number, context: string = "instructions") {
   102→    const stmtPrefix = `${context}[${index}]`;
   103→
   104→    switch (stmt.type) {
   105→      case "var":
   106→        this.checkVarDecl(stmt, stmtPrefix);
   107→        break;
   108→      case "assign":
   109→        this.checkAssign(stmt, stmtPrefix);
   110→        break;
   111→      case "return":
   112→        this.checkReturn(stmt, stmtPrefix);
   113→        break;
   114→      case "condition":
   115→        this.checkCondition(stmt, stmtPrefix);
   116→        break;
   117→      case "for":
   118→        this.checkFor(stmt, stmtPrefix);
   119→        break;
   120→      case "while":
   121→        this.checkWhile(stmt, stmtPrefix);
   122→        break;
   123→      case "match":
   124→        this.checkMatch(stmt, stmtPrefix);
   125→        break;
   126→      case "call":
   127→      case "method_call":
   128→        this.checkCall(stmt, stmtPrefix);
   129→        break;
   130→      case "try":
   131→        this.checkTry(stmt, stmtPrefix);
   132→        break;
   133→    }
   134→  }
   135→
   136→  /**
   137→   * 변수 선언 검사
   138→   */
   139→  private checkVarDecl(stmt: any, prefix: string) {
   140→    const varType = stmt.value_type || this.inferType(stmt.value);
   141→
   142→    if (!varType) {
   143→      this.errors.push({
   144→        message: `${prefix}: ${stmt.name}의 타입을 추론할 수 없습니다`,
   145→        code: "TYPE_INFERENCE_FAILED",
   146→      });
   147→      return;
   148→    }
   149→
   150→    // 값의 타입 검사
   151→    const valueType = this.getExpressionType(stmt.value);
   152→    if (valueType && !this.isCompatible(varType, valueType)) {
   153→      this.errors.push({
   154→        message: `${prefix}: 타입 불일치 - ${this.typeToString(varType)}을(를) 기대했으나 ${this.typeToString(valueType)} 받음`,
   155→        code: "TYPE_MISMATCH",
   156→      });
   157→      return;
   158→    }
   159→
   160→    // 변수 등록
   161→    this.setVariable(stmt.name, varType);
   162→  }
   163→
   164→  /**
   165→   * 변수 재할당 검사
   166→   */
   167→  private checkAssign(stmt: any, prefix: string) {
   168→    const varType = this.getVariable(stmt.name);
   169→    if (!varType) {
   170→      this.errors.push({
   171→        message: `${prefix}: 정의되지 않은 변수 "${stmt.name}"`,
   172→        code: "UNDEFINED_VARIABLE",
   173→      });
   174→      return;
   175→    }
   176→
   177→    const valueType = this.getExpressionType(stmt.value);
   178→    if (valueType && !this.isCompatible(varType, valueType)) {
   179→      this.errors.push({
   180→        message: `${prefix}: 타입 불일치 - ${this.typeToString(varType)}을(를) 기대했으나 ${this.typeToString(valueType)} 받음`,
   181→        code: "TYPE_MISMATCH",
   182→      });
   183→    }
   184→  }
   185→
   186→  /**
   187→   * Return 문 검사
   188→   */
   189→  private checkReturn(stmt: any, prefix: string) {
   190→    if (stmt.value) {
   191→      const returnType = this.getExpressionType(stmt.value);
   192→      // 실제 함수의 반환 타입과 비교는 나중에 함수 컨텍스트에서 수행
   193→    }
   194→  }
   195→
   196→  /**
   197→   * 조건문 검사
   198→   */
   199→  private checkCondition(stmt: any, prefix: string) {
   200→    // 조건식이 bool 타입인지 검사
   201→    const testType = this.getExpressionType(stmt.test);
   202→    if (testType && !this.isBoolType(testType)) {
   203→      this.errors.push({
   204→        message: `${prefix}: 조건식은 bool 타입이어야 합니다. 받은 타입: ${this.typeToString(testType)}`,
   205→        code: "CONDITION_TYPE_ERROR",
   206→      });
   207→    }
   208→
   209→    // then 블록 검사
   210→    for (let i = 0; i < stmt.then.length; i++) {
   211→      this.checkStatement(stmt.then[i], i, `${prefix}.then`);
   212→    }
   213→
   214→    // else 블록 검사
   215→    if (stmt.else) {
   216→      for (let i = 0; i < stmt.else.length; i++) {
   217→        this.checkStatement(stmt.else[i], i, `${prefix}.else`);
   218→      }
   219→    }
   220→  }
   221→
   222→  /**
   223→   * For 루프 검사
   224→   */
   225→  private checkFor(stmt: any, prefix: string) {
   226→    // 범위의 시작과 끝이 정수 타입인지 검사
   227→    const startType = this.getExpressionType(stmt.range.start);
   228→    const endType = this.getExpressionType(stmt.range.end);
   229→
   230→    if (startType && !this.isIntegerType(startType)) {
   231→      this.errors.push({
   232→        message: `${prefix}: 루프 범위의 시작은 정수 타입이어야 합니다`,
   233→        code: "RANGE_TYPE_ERROR",
   234→      });
   235→    }
   236→
   237→    if (endType && !this.isIntegerType(endType)) {
   238→      this.errors.push({
   239→        message: `${prefix}: 루프 범위의 끝은 정수 타입이어야 합니다`,
   240→        code: "RANGE_TYPE_ERROR",
   241→      });
   242→    }
   243→
   244→    // 루프 변수를 정수 타입으로 등록
   245→    this.setVariable(stmt.variable, { base: "i32" });
   246→
   247→    // 루프 본체 검사
   248→    for (let i = 0; i < stmt.body.length; i++) {
   249→      this.checkStatement(stmt.body[i], i, `${prefix}.body`);
   250→    }
   251→  }
   252→
   253→  /**
   254→   * While 루프 검사
   255→   */
   256→  private checkWhile(stmt: any, prefix: string) {
   257→    const condType = this.getExpressionType(stmt.condition);
   258→    if (condType && !this.isBoolType(condType)) {
   259→      this.errors.push({
   260→        message: `${prefix}: 루프 조건은 bool 타입이어야 합니다`,
   261→        code: "CONDITION_TYPE_ERROR",
   262→      });
   263→    }
   264→
   265→    // 루프 본체 검사
   266→    for (let i = 0; i < stmt.body.length; i++) {
   267→      this.checkStatement(stmt.body[i], i, `${prefix}.body`);
   268→    }
   269→  }
   270→
   271→  /**
   272→   * Match (패턴 매칭) 검사
   273→   */
   274→  private checkMatch(stmt: any, prefix: string) {
   275→    const valueType = this.getExpressionType(stmt.value);
   276→
   277→    // Option 타입인지 확인
   278→    if (
   279→      !valueType ||
   280→      valueType.base !== "Option"
   281→    ) {
   282→      this.errors.push({
   283→        message: `${prefix}: match는 Option 타입에만 사용 가능합니다. 받은 타입: ${this.typeToString(valueType || { base: "unknown" })}`,
   284→        code: "MATCH_TYPE_ERROR",
   285→      });
   286→    }
   287→
   288→    // 각 케이스 검사
   289→    for (const caseItem of stmt.cases) {
   290→      if (caseItem.bind && valueType && valueType.base === "Option") {
   291→        // Some 케이스: 바인딩된 변수의 타입 설정
   292→        const elemType = this.getTypeProperty(valueType, "element_type") || { base: "unknown" };
   293→        this.setVariable(caseItem.bind, elemType);
   294→      }
   295→
   296→      for (let i = 0; i < caseItem.body.length; i++) {
   297→        this.checkStatement(caseItem.body[i], i, `${prefix}.case(${caseItem.pattern})`);
   298→      }
   299→    }
   300→  }
   301→
   302→  /**
   303→   * 함수 호출 검사
   304→   */
   305→  private checkCall(stmt: any, prefix: string) {
   306→    const funcInfo = this.functions[stmt.function];
   307→
   308→    if (!funcInfo && !this.isBuiltinFunction(stmt.function)) {
   309→      this.errors.push({
   310→        message: `${prefix}: 정의되지 않은 함수 "${stmt.function}"`,
   311→        code: "UNDEFINED_FUNCTION",
   312→      });
   313→      return;
   314→    }
   315→
   316→    if (funcInfo) {
   317→      // 인자 개수 검사
   318→      if (stmt.args.length !== funcInfo.params.length) {
   319→        this.errors.push({
   320→          message: `${prefix}: ${stmt.function}은 ${funcInfo.params.length}개의 인자를 기대하나 ${stmt.args.length}개 받음`,
   321→          code: "ARGUMENT_COUNT_MISMATCH",
   322→        });
   323→      }
   324→
   325→      // 인자 타입 검사
   326→      for (let i = 0; i < Math.min(stmt.args.length, funcInfo.params.length); i++) {
   327→        const argType = this.getExpressionType(stmt.args[i]);
   328→        const paramType = funcInfo.params[i].type;
   329→
   330→        if (argType && !this.isCompatible(paramType, argType)) {
   331→          this.errors.push({
   332→            message: `${prefix}: 인자 ${i + 1}의 타입 불일치 - ${this.typeToString(paramType)}을(를) 기대했으나 ${this.typeToString(argType)} 받음`,
   333→            code: "ARGUMENT_TYPE_MISMATCH",
   334→          });
   335→        }
   336→      }
   337→    }
   338→
   339→    // 반환값이 할당되는 경우
   340→    if (stmt.assign_to && funcInfo) {
   341→      this.setVariable(stmt.assign_to, funcInfo.return_type);
   342→    }
   343→  }
   344→
   345→  /**
   346→   * Try/Catch 검사
   347→   */
   348→  private checkTry(stmt: any, prefix: string) {
   349→    // try 블록
   350→    for (let i = 0; i < stmt.body.length; i++) {
   351→      this.checkStatement(stmt.body[i], i, `${prefix}.try`);
   352→    }
   353→
   354→    // catch 블록
   355→    if (stmt.catch) {
   356→      this.setVariable(stmt.catch.error_var, { base: "string" });
   357→      for (let i = 0; i < stmt.catch.body.length; i++) {
   358→        this.checkStatement(stmt.catch.body[i], i, `${prefix}.catch`);
   359→      }
   360→    }
   361→
   362→    // finally 블록
   363→    if (stmt.finally) {
   364→      for (let i = 0; i < stmt.finally.length; i++) {
   365→        this.checkStatement(stmt.finally[i], i, `${prefix}.finally`);
   366→      }
   367→    }
   368→  }
   369→
   370→  /**
   371→   * 표현식의 타입 얻기
   372→   */
   373→  private getExpressionType(expr: any): TypeSpec | null {
   374→    if (!expr) return null;
   375→
   376→    switch (expr.type) {
   377→      case "literal":
   378→        return { base: expr.value_type };
   379→      case "ref":
   380→        return this.getVariable(expr.name);
   381→      case "binary_op":
   382→        return this.getBinaryOpType(expr);
   383→      case "unary_op":
   384→        return this.getUnaryOpType(expr);
   385→      case "call":
   386→        return this.getCallReturnType(expr);
   387→      case "index":
   388→        return this.getIndexType(expr);
   389→      case "some": {
   390→        const val = this.getExpressionType(expr.value) || { base: "unknown" };
   391→        const result: any = { base: "Option", element_type: val };
   392→        return result as TypeSpec;
   393→      }
   394→      case "none": {
   395→        const result: any = { base: "Option", element_type: { base: "unknown" } };
   396→        return result as TypeSpec;
   397→      }
   398→      case "literal_array":
   399→        return {
   400→          base: "Array",
   401→          element_type: expr.element_type,
   402→        };
   403→      default:
   404→        return null;
   405→    }
   406→  }
   407→
   408→  /**
   409→   * 이항 연산 타입
   410→   */
   411→  private getBinaryOpType(expr: any): TypeSpec | null {
   412→    const leftType = this.getExpressionType(expr.left);
   413→    const rightType = this.getExpressionType(expr.right);
   414→
   415→    if (!leftType || !rightType) return null;
   416→
   417→    // 산술 연산
   418→    if (["+", "-", "*", "/", "%"].includes(expr.op)) {
   419→      if (this.isCompatible(leftType, rightType)) {
   420→        return leftType;
   421→      }
   422→      return null;
   423→    }
   424→
   425→    // 비교 연산
   426→    if (["==", "!=", "<", ">", "<=", ">="].includes(expr.op)) {
   427→      return { base: "bool" };
   428→    }
   429→
   430→    // 논리 연산
   431→    if (["&&", "||"].includes(expr.op)) {
   432→      return { base: "bool" };
   433→    }
   434→
   435→    return null;
   436→  }
   437→
   438→  private getTypeProperty(type: TypeSpec, prop: string): TypeSpec | undefined {
   439→    const anyType = type as any;
   440→    return anyType[prop];
   441→  }
   442→
   443→  /**
   444→   * 단항 연산 타입
   445→   */
   446→  private getUnaryOpType(expr: any): TypeSpec | null {
   447→    const operandType = this.getExpressionType(expr.operand);
   448→
   449→    if (!operandType) return null;
   450→
   451→    if (expr.op === "-") {
   452→      return operandType;  // 부호 반전은 같은 타입 반환
   453→    }
   454→
   455→    if (expr.op === "!") {
   456→      return { base: "bool" };  // 논리 부정은 bool 반환
   457→    }
   458→
   459→    return null;
   460→  }
   461→
   462→  /**
   463→   * 함수 호출의 반환 타입
   464→   */
   465→  private getCallReturnType(expr: any): TypeSpec | null {
   466→    const funcInfo = this.functions[expr.function];
   467→    if (funcInfo) {
   468→      return funcInfo.return_type;
   469→    }
   470→
   471→    // 내장 함수
   472→    if (expr.function === "to_string") return { base: "string" };
   473→    if (expr.function === "to_i32") return { base: "i32" };
   474→    if (expr.function === "to_f64") return { base: "f64" };
   475→    if (expr.function === "length") return { base: "i32" };
   476→
   477→    return null;
   478→  }
   479→
   480→  /**
   481→   * 배열 인덱싱 타입
   482→   */
   483→  private getIndexType(expr: any): TypeSpec | null {
   484→    const arrayType = this.getExpressionType(expr.array);
   485→    const indexType = this.getExpressionType(expr.index);
   486→
   487→    if (!arrayType || !indexType) return null;
   488→
   489→    // 인덱스는 정수여야 함
   490→    if (!this.isIntegerType(indexType)) {
   491→      this.errors.push({
   492→        message: `배열 인덱스는 정수 타입이어야 합니다. 받은 타입: ${this.typeToString(indexType)}`,
   493→        code: "INDEX_TYPE_ERROR",
   494→      });
   495→      return null;
   496→    }
   497→
   498→    // 배열 타입이어야 함
   499→    if (arrayType.base !== "Array") {
   500→      this.errors.push({
   501→        message: `배열 인덱싱은 Array 타입에만 사용 가능합니다. 받은 타입: ${this.typeToString(arrayType)}`,
   502→        code: "INDEX_ON_NON_ARRAY",
   503→      });
   504→      return null;
   505→    }
   506→
   507→    // 원소 타입 반환
   508→    const elemType = this.getTypeProperty(arrayType, "element_type") || { base: "unknown" };
   509→    return elemType;
   510→  }
   511→
   512→  /**
   513→   * 타입 추론
   514→   */
   515→  private inferType(expr: any): TypeSpec | null {
   516→    if (expr.type === "literal") {
   517→      return { base: expr.value_type };
   518→    }
   519→    if (expr.type === "literal_array") {
   520→      return {
   521→        base: "Array",
   522→        element_type: expr.element_type,
   523→      };
   524→    }
   525→    return null;
   526→  }
   527→
   528→  /**
   529→   * 타입 호환성 검사
   530→   */
   531→  private isCompatible(expected: TypeSpec, actual: TypeSpec): boolean {
   532→    // 같은 기본 타입
   533→    if (expected.base === actual.base) {
   534→      // 복합 타입의 경우 재귀적으로 검사
   535→      if (expected.base === "Array" && actual.base === "Array") {
   536→        const expectedElem = this.getTypeProperty(expected, "element_type") || { base: "unknown" };
   537→        const actualElem = this.getTypeProperty(actual, "element_type") || { base: "unknown" };
   538→        return this.isCompatible(expectedElem, actualElem);
   539→      }
   540→      if (expected.base === "Option" && actual.base === "Option") {
   541→        const expectedElem = this.getTypeProperty(expected, "element_type") || { base: "unknown" };
   542→        const actualElem = this.getTypeProperty(actual, "element_type") || { base: "unknown" };
   543→        return this.isCompatible(expectedElem, actualElem);
   544→      }
   545→      return true;
   546→    }
   547→
   548→    // 암묵적 변환 금지
   549→    return false;
   550→  }
   551→
   552→  /**
   553→   * Bool 타입 확인
   554→   */
   555→  private isBoolType(type: TypeSpec): boolean {
   556→    return type.base === "bool";
   557→  }
   558→
   559→  /**
   560→   * 정수 타입 확인
   561→   */
   562→  private isIntegerType(type: TypeSpec): boolean {
   563→    return type.base === "i32" || type.base === "i64";
   564→  }
   565→
   566→  /**
   567→   * 내장 함수 확인
   568→   */
   569→  private isBuiltinFunction(name: string): boolean {
   570→    const builtins = [
   571→      "println",
   572→      "print",
   573→      "to_string",
   574→      "to_i32",
   575→      "to_f64",
   576→      "length",
   577→      "Array.get",
   578→      "Array.set",
   579→      "Array.push",
   580→      "Array.pop",
   581→    ];
   582→    return builtins.includes(name);
   583→  }
   584→
   585→  /**
   586→   * 변수 등록
   587→   */
   588→  private setVariable(name: string, type: TypeSpec) {
   589→    const currentScope = this.scopes[this.scopes.length - 1];
   590→    currentScope[name] = type;
   591→    this.variables[name] = type;
   592→  }
   593→
   594→  /**
   595→   * 변수 조회
   596→   */
   597→  private getVariable(name: string): TypeSpec | null {
   598→    // 현재 스코프부터 역순으로 탐색
   599→    for (let i = this.scopes.length - 1; i >= 0; i--) {
   600→      if (this.scopes[i][name]) {
   601→        return this.scopes[i][name];
   602→      }
   603→    }
   604→    return null;
   605→  }
   606→
   607→  /**
   608→   * 타입을 문자열로 변환
   609→   */
   610→  private typeToString(type: TypeSpec): string {
   611→    if (type.base === "Array") {
   612→      const elemType = this.getTypeProperty(type, "element_type") || { base: "unknown" };
   613→      return `Array<${this.typeToString(elemType)}>`;
   614→    }
   615→    if (type.base === "Option") {
   616→      const elemType = this.getTypeProperty(type, "element_type") || { base: "unknown" };
   617→      return `Option<${this.typeToString(elemType)}>`;
   618→    }
   619→    if (type.base === "Map") {
   620→      const keyType = this.getTypeProperty(type, "key_type") || { base: "unknown" };
   621→      const valueType = this.getTypeProperty(type, "value_type") || { base: "unknown" };
   622→      return `Map<${this.typeToString(keyType)}, ${this.typeToString(valueType)}>`;
   623→    }
   624→    return type.base;
   625→  }
   626→}
   627→
   628→export function checkTypes(ast: Program): TypeCheckResult {
   629→  const checker = new TypeChecker();
   630→  return checker.checkProgram(ast);
   631→}
