   143→    fn test_memory_read_write() {
   144→        let mut mem = Memory::new();
   145→        mem.write(0, 42).unwrap();
   146→        assert_eq!(mem.read(0).unwrap(), 42);
   147→    }
   148→
   149→    #[test]
   150→    fn test_memory_bounds() {
   151→        let mut mem = Memory::new();
   152→        let result = mem.write(MEMORY_SIZE, 0);
   153→        assert!(result.is_err());
   154→    }
   155→
   156→    #[test]
   157→    fn test_stack_push_pop() {
   158→        let mut mem = Memory::new();
   159→        let mut sp = 0;
   160→
