   168→
   169→    #[test]
   170→    fn test_stack_overflow() {
   171→        let mut mem = Memory::new();
   172→        let mut sp = STACK_END;
   173→        let result = mem.stack_push(&mut sp, 0);
   174→        assert!(result.is_err());
   175→    }
   176→
   177→    #[test]
   178→    fn test_stack_underflow() {
