    27→/**
    28→ * print(value: any): null
    29→ * Writes value to stdout without newline
    30→ */
    31→function print(value) {
    32→  process.stdout.write(String(value));
    33→  return null;
    34→}
    35→
    36→/**
    37→ * println(value: any): null
    38→ * Writes value to stdout with newline
