    42→  return null;
    43→}
    44→
    45→/**
    46→ * read_file(path: string): {ok: boolean, value?: string, error?: string}
    47→ * Reads file contents, returns Result<string>
    48→ */
    49→function read_file(filepath) {
    50→  try {
    51→    const content = fs.readFileSync(filepath, 'utf8');
    52→    return { ok: true, value: content, error: null };
    53→  } catch (err) {
    54→    return { ok: false, value: null, error: err.message };
    55→  }
    56→}
