   538→function assert_eq(actual, expected, message = '') {
   539→  // Direct comparison
   540→  if (actual === expected) {
   541→    return null;
   542→  }
   543→  // JSON comparison
   544→  if (JSON.stringify(actual) === JSON.stringify(expected)) {
   545→    return null;
   546→  }
   547→  // Loose comparison for type conversion
   548→  if (actual == expected) {
