   591→
   592→/**
   593→ * replace(s: string, search: string, replacement: string): string
   594→ * Replaces first occurrence
   595→ */
   596→function replace(s, search, replacement) {
   597→  const str = String(s);
   598→  const search_str = String(search);
   599→  const repl_str = String(replacement);
   600→  const idx = str.indexOf(search_str);
   601→  if (idx === -1) return str;
   602→  return str.slice(0, idx) + repl_str + str.slice(idx + search_str.length);
   603→}
