  { op: OpCode.MUL },

  { op: OpCode.RET },
  { op: OpCode.HALT }
];

try {
  const vm2 = new FreeLangVM(program2);
  const result2 = vm2.run();
  if (result2 === 42) {
    console.log(`✅ PASS: ${result2} === 42\n`);
  } else {
    console.log(`❌ FAIL: ${result2} !== 42\n`);
  }
