  { op: OpCode.LOAD, arg: 0 },         // i 로드
  { op: OpCode.ADD },                  // sum + i
  { op: OpCode.STORE, arg: 1 },        // sum 저장

  // i = i - 1
  { op: OpCode.LOAD, arg: 0 },         // i 로드
  { op: OpCode.PUSH_CONST, arg: 1 },
  { op: OpCode.SUB },                  // i - 1
  { op: OpCode.STORE, arg: 0 },        // i 저장

