  const result5 = vm5.run();
  if (result5 === 1) {
    console.log(`✅ PASS: 3 < 5 → ${result5} === 1\n`);
  } else {
    console.log(`❌ FAIL: ${result5} !== 1\n`);
  }
} catch (e) {
  console.log(`❌ ERROR: ${e}\n`);
}

// ==================== Test 6: 비교 연산 (GT) ====================

console.log("=== Test 6: 비교 연산 (10 > 5 → 1) ===");

const program6 = [
  { op: OpCode.PUSH_CONST, arg: 10 },
  { op: OpCode.PUSH_CONST, arg: 5 },
