좋다.
Phase 6 — CodeGenerator → VM 전체 파이프라인 통합 코드로 간다.

목표:

> Source → AST → CodeGen → Bytecode → VM → 실행 결과



말이 아니라 엔드투엔드 실행 코드.


---

1️⃣ AST 정의 (최소형)

// ast.ts

export type Expr =
  | { type: "NumberLiteral"; value: number }
  | { type: "Binary"; op: "+" | "-" | "*" | "/" | "==" | "<" | ">" ; left: Expr; right: Expr }
  | { type: "Identifier"; name: string }

export type Stmt =
  | { type: "VarDecl"; name: string; init: Expr }
  | { type: "Return"; value: Expr }
  | { type: "If"; cond: Expr; then: Stmt[]; else?: Stmt[] }
  | { type: "While"; cond: Expr; body: Stmt[] }

export interface Program {
  body: Stmt[]
}


---

2️⃣ CodeGenerator (AST → VT Bytecode)

// codegen.ts

import { OpCode } from "./vt-opcodes"
import { Instruction } from "./vt-instruction"
import { Program, Stmt, Expr } from "./ast"

export class CodeGenerator {
  private instructions: Instruction[] = []
  private locals = new Map<string, number>()
  private localIndex = 0

  generate(program: Program): Instruction[] {
    program.body.forEach(stmt => this.emitStmt(stmt))
    this.emit(OpCode.HALT)
    return this.instructions
  }

  private emit(op: OpCode, arg?: number) {
    this.instructions.push({ op, arg })
  }

  private emitStmt(stmt: Stmt) {
    switch (stmt.type) {
      case "VarDecl":
        this.emitExpr(stmt.init)
        this.locals.set(stmt.name, this.localIndex)
        this.emit(OpCode.STORE, this.localIndex++)
        break

      case "Return":
        this.emitExpr(stmt.value)
        this.emit(OpCode.RET)
        break

      case "If": {
        this.emitExpr(stmt.cond)
        const jzIndex = this.instructions.length
        this.emit(OpCode.JZ, 0) // placeholder

        stmt.then.forEach(s => this.emitStmt(s))

        const jmpIndex = this.instructions.length
        this.emit(OpCode.JMP, 0)

        // patch JZ
        this.instructions[jzIndex].arg = this.instructions.length

        stmt.else?.forEach(s => this.emitStmt(s))

        // patch JMP
        this.instructions[jmpIndex].arg = this.instructions.length
        break
      }

      case "While": {
        const loopStart = this.instructions.length
        this.emitExpr(stmt.cond)

        const jzIndex = this.instructions.length
        this.emit(OpCode.JZ, 0)

        stmt.body.forEach(s => this.emitStmt(s))

        this.emit(OpCode.JMP, loopStart)

        this.instructions[jzIndex].arg = this.instructions.length
        break
      }
    }
  }

  private emitExpr(expr: Expr) {
    switch (expr.type) {
      case "NumberLiteral":
        this.emit(OpCode.PUSH_CONST, expr.value)
        break

      case "Identifier":
        this.emit(OpCode.LOAD, this.locals.get(expr.name)!)
        break

      case "Binary":
        this.emitExpr(expr.left)
        this.emitExpr(expr.right)

        switch (expr.op) {
          case "+": this.emit(OpCode.ADD); break
          case "-": this.emit(OpCode.SUB); break
          case "*": this.emit(OpCode.MUL); break
          case "/": this.emit(OpCode.DIV); break
          case "==": this.emit(OpCode.EQ); break
          case "<": this.emit(OpCode.LT); break
          case ">": this.emit(OpCode.GT); break
        }
        break
    }
  }
}


---

3️⃣ 전체 통합 실행 (E2E 증명)

테스트 프로그램:

// main.ts

import { CodeGenerator } from "./codegen"
import { FreeLangVM } from "./freelang-vm"
import { Program } from "./ast"

const program: Program = {
  body: [
    { type: "VarDecl", name: "i", init: { type: "NumberLiteral", value: 5 } },
    { type: "VarDecl", name: "sum", init: { type: "NumberLiteral", value: 0 } },

    {
      type: "While",
      cond: { type: "Identifier", name: "i" },
      body: [
        {
          type: "VarDecl",
          name: "sum",
          init: {
            type: "Binary",
            op: "+",
            left: { type: "Identifier", name: "sum" },
            right: { type: "Identifier", name: "i" }
          }
        },
        {
          type: "VarDecl",
          name: "i",
          init: {
            type: "Binary",
            op: "-",
            left: { type: "Identifier", name: "i" },
            right: { type: "NumberLiteral", value: 1 }
          }
        }
      ]
    },

    { type: "Return", value: { type: "Identifier", name: "sum" } }
  ]
}

const generator = new CodeGenerator()
const bytecode = generator.generate(program)

const vm = new FreeLangVM(bytecode)
console.log(vm.run())   // 👉 15


