# Phase 8: Source Code Parser (Lexer + Parser) ✅ COMPLETE

**Date**: 2026-03-07
**Status**: COMPLETE
**Tests**: 5/5 passing ✅

## Overview

Phase 8 eliminates the need for JSON AST input. The language now accepts **real source code** as text and compiles it directly through a complete pipeline.

```
Source Code → Lexer → Parser → AST → CodeGen → VM → Result
```

This is the final piece for practical language usage.

## Architecture

```
┌─────────────────────────────────────────────┐
│  Phase 8: Source Code Parser                │
├─────────────────────────────────────────────┤
│                                             │
│  Lexer (src/lexer.ts)                      │
│  ├─ skipWhitespaceAndComments()            │
│  ├─ scanNumber() → NUMBER token            │
│  ├─ scanIdentifier() → IDENTIFIER/KEYWORD  │
│  └─ tokenize() → Token[]                   │
│                                             │
│  Parser (src/parser.ts)                    │
│  ├─ statement()                            │
│  │  ├─ let declaration                     │
│  │  ├─ while/if blocks                     │
│  │  ├─ assignment (x = value)              │
│  │  └─ function calls                      │
│  ├─ expression()                           │
│  │  ├─ comparison (==, <, >)              │
│  │  ├─ addition (+, -)                     │
│  │  ├─ multiplication (*, /)               │
│  │  ├─ call (func(args))                   │
│  │  └─ primary (number, identifier, ())    │
│  └─ parse() → Program (AST)               │
│                                             │
└─────────────────────────────────────────────┘
```

## Implementation Details

### 1. Lexer (`src/lexer.ts`)

**TokenType Enum** (17 types):
```typescript
// Literals
NUMBER, IDENTIFIER

// Keywords
LET, WHILE, IF, ELSE, RETURN

// Operators
PLUS, MINUS, STAR, SLASH, EQ_EQ, LT, GT, EQ

// Punctuation
LPAREN, RPAREN, LBRACE, RBRACE, SEMICOLON, COMMA

// Special
EOF
```

**Key Methods**:
```typescript
class Lexer {
  tokenize(): Token[] {
    // Main tokenization loop
    // Handles all token types, whitespace, comments
  }

  private scanNumber() {
    // Parse integer literals
    // Example: 123 → Token(NUMBER, value: 123)
  }

  private scanIdentifier() {
    // Parse identifiers and keywords
    // Example: let → Token(LET), x → Token(IDENTIFIER)
  }

  private skipWhitespaceAndComments() {
    // Skip whitespace (space, \n, \r, \t)
    // Skip line comments (//)
  }
}
```

### 2. Parser (`src/parser.ts`)

**Recursive Descent Parser** with operator precedence:

```typescript
class Parser {
  parse(): Program {
    const body: Stmt[] = [];
    while (!isAtEnd()) {
      body.push(statement());
    }
    return { body };
  }

  // Statement parsing
  private statement(): Stmt {
    if (match(LET)) return varDeclStatement();
    if (match(WHILE)) return whileStatement();
    if (match(IF)) return ifStatement();
    if (match(RETURN)) return returnStatement();

    // Assignment or function call
    const expr = expression();
    if (expr.type === "Identifier" && match(EQ)) {
      const value = expression();
      return { type: "VarDecl", name: expr.name, init: value };
    }
    if (expr.type === "Call") return expr;
    throw new Error("Expected statement");
  }

  // Expression parsing (operator precedence)
  private expression(): Expr {
    return comparison();
  }

  private comparison(): Expr {
    let expr = addition();
    while (match(EQ_EQ, LT, GT)) {
      const op = previous().lexeme;
      const right = addition();
      expr = { type: "Binary", op, left: expr, right };
    }
    return expr;
  }

  private addition(): Expr {
    let expr = multiplication();
    while (match(PLUS, MINUS)) {
      const op = previous().lexeme;
      const right = multiplication();
      expr = { type: "Binary", op, left: expr, right };
    }
    return expr;
  }

  private multiplication(): Expr {
    let expr = call();
    while (match(STAR, SLASH)) {
      const op = previous().lexeme;
      const right = call();
      expr = { type: "Binary", op, left: expr, right };
    }
    return expr;
  }

  private call(): Expr {
    let expr = primary();
    if (expr.type === "Identifier" && check(LPAREN)) {
      this.advance();
      const args: Expr[] = [];
      if (!check(RPAREN)) {
        do { args.push(expression()); } while (match(COMMA));
      }
      this.consume(RPAREN, "Expected ')'");
      return { type: "Call", name: expr.name, args };
    }
    return expr;
  }

  private primary(): Expr {
    if (match(NUMBER)) return { type: "NumberLiteral", value };
    if (match(IDENTIFIER)) return { type: "Identifier", name };
    if (match(LPAREN)) {
      const expr = expression();
      this.consume(RPAREN, "Expected ')'");
      return expr;
    }
    throw new Error(`Unexpected token: ${peek().lexeme}`);
  }
}
```

## Supported Grammar

### Variable Declaration
```
let x = 10;
let y = x + 5;
```

### Assignment
```
x = 20;
y = y - 1;
```

### While Loop
```
while (x > 0) {
  println(x);
  x = x - 1;
}
```

### If-Else Statement
```
if (x > 5) {
  println(100);
} else {
  println(50);
}
```

### Function Call
```
println(42);
print(x + y);
```

### Operators
```
x + y      // Addition
x - y      // Subtraction
x * y      // Multiplication
x / y      // Division
x == y     // Equality
x < y      // Less than
x > y      // Greater than
```

### Comments
```
// This is a line comment
let x = 10; // inline comment
```

## Test Coverage (5/5 ✅)

### Test 1: Simple Arithmetic
```
Source:
