  println(200);
}
return 0;

Output: 100 ✅
```

### Test 4: Factorial
```
Source:
let n = 5;
let result = 1;
while (n > 1) {
  result = result * n;
  n = n - 1;
}
println(result);
return result;

Output:
120
Result: 120 ✅
```

### Test 5: Nested Control Flow
```
Source:
let i = 3;
while (i > 0) {
  if (i == 2) {
    println(999);
  } else {
    println(i);
  }
  i = i - 1;
}
return 0;

Output:
